const generateCC = (nepaliConsonants: any) =>
  nepaliConsonants
    .map((conA: any) => {
      return nepaliConsonants?.map((conB: any) => {
        if (conA?.nepali === "द") {
          if (
            !["ग", "घ", "द", "ध", "न", "ब", "भ", "म", "य", "र", "व"]?.includes(
              conB?.nepali
            )
          ) {
            return {
              nepali: null,
              en: null,
              first: conA?.nepali,
              last: conB?.nepali,
            };
          }
        }
        return {
          nepali: conA?.nepali + "्" + conB?.nepali,
          en: conA?.en?.slice(0, -1) + conB?.en,
          first: conA?.nepali,
          last: conB?.nepali,
        };
      });
    })
    .flat();

